<template>
  <main class="public-page">
    <header class="masthead"><div class="masthead__inner"><span class="masthead__icon material-icons-outlined">directions_bus</span><div><p>福清市车务管理系统</p><h1>通勤路线</h1></div></div></header>
    <section class="content" aria-live="polite">
      <div class="intro"><div><p class="eyebrow">COMMUTE ROUTES</p><h2>班车线路与停靠时间</h2></div><button class="refresh" title="刷新路线" type="button" @click="load"><span class="material-icons-outlined">refresh</span></button></div>
      <p v-if="errorMessage" class="state state--error"><span class="material-icons-outlined">error_outline</span>{{ errorMessage }}</p>
      <p v-else-if="loading" class="state"><span class="material-icons-outlined spin">progress_activity</span>正在加载路线...</p>
      <p v-else-if="routes.length === 0" class="state"><span class="material-icons-outlined">route</span>暂未发布通勤路线</p>
      <div v-else class="route-list"><article v-for="route in routes" :key="route.id" class="route"><button :aria-expanded="expanded === route.id" class="route__summary" type="button" @click="toggle(route.id)"><span class="route__mark material-icons-outlined">route</span><span class="route__title"><strong>{{ route.route_name }}</strong><small>{{ route.start_address }} 至 {{ route.end_address }}</small></span><span class="route__time">{{ route.route_stops[0]?.time || "--:--" }}<i/>{{ route.route_stops.at(-1)?.time || "--:--" }}</span><span class="material-icons-outlined chevron">expand_more</span></button><div v-show="expanded === route.id" class="route__detail"><p v-if="route.remark" class="route__remark"><span class="material-icons-outlined">info</span>{{ route.remark }}</p><ol class="stops"><li v-for="(stop, index) in route.route_stops" :key="`${stop.name}-${stop.time}`"><span class="stop__time">{{ stop.time }}</span><span class="stop__line"/><span class="stop__name">{{ stop.name }}</span><span v-if="index === 0" class="stop__tag">始发</span><span v-else-if="index === route.route_stops.length - 1" class="stop__tag">终点</span></li></ol></div></article></div>
    </section>
  </main>
</template>

<script lang="ts" setup>
interface Stop { name: string; time: string }
interface CommuteRoute { id: number; route_name: string; start_address: string; end_address: string; route_stops: Stop[]; remark?: string | null }
const http = useHttp(); const routes = ref<CommuteRoute[]>([]); const loading = ref(true); const errorMessage = ref(""); const expanded = ref<number | null>(null);
function toggle(id: number) { expanded.value = expanded.value === id ? null : id; }
async function load() { loading.value = true; errorMessage.value = ""; try { const result = await http.get<{items: CommuteRoute[]}>("/commute-routes/public"); routes.value = result.items || []; if (routes.value.length && !routes.value.some((route) => route.id === expanded.value)) expanded.value = routes.value[0].id; } catch (error) { errorMessage.value = (error as {statusMessage?: string}).statusMessage || "路线暂时无法获取，请稍后重试"; } finally { loading.value = false; } }
useHead({title: "通勤路线"}); onMounted(load);
</script>

<style scoped>
.public-page { background: var(--bg); min-height: 100dvh; }.masthead { background: var(--primary); color: var(--on-solid); }.masthead__inner { align-items: center; display: flex; gap: 12px; margin: 0 auto; max-width: 920px; min-height: 112px; padding: 0 24px; }.masthead__icon { align-items: center; background: color-mix(in srgb, var(--on-solid) 18%, transparent); border-radius: 6px; display: flex; font-size: 30px; height: 52px; justify-content: center; width: 52px; }.masthead p { font-size: 12px; margin: 0 0 3px; opacity: .78; }.masthead h1 { font-size: 25px; font-weight: 650; letter-spacing: 0; margin: 0; }.content { margin: 0 auto; max-width: 920px; padding: 28px 24px 48px; }.intro { align-items: end; display: flex; justify-content: space-between; margin-bottom: 18px; }.eyebrow { color: var(--primary); font-size: 11px; font-weight: 700; letter-spacing: 0; margin: 0 0 6px; }.intro h2 { color: var(--text); font-size: 20px; font-weight: 650; margin: 0; }.refresh { align-items: center; background: var(--card); border: 1px solid var(--border-strong); border-radius: 6px; color: var(--text-sub); cursor: pointer; display: inline-flex; height: 36px; justify-content: center; width: 36px; }.refresh:hover { background: var(--primary-soft); color: var(--primary); }.refresh .material-icons-outlined { font-size: 19px; }.route-list { display: grid; gap: 12px; }.route { background: var(--card); border: 1px solid var(--border-strong); border-radius: 8px; overflow: hidden; }.route__summary { align-items: center; background: transparent; border: 0; color: var(--text); cursor: pointer; display: grid; gap: 14px; grid-template-columns: 38px minmax(0, 1fr) auto 24px; min-height: 76px; padding: 12px 18px; text-align: left; width: 100%; }.route__summary:hover { background: var(--bg); }.route__mark { align-items: center; background: var(--primary-soft); border-radius: 6px; color: var(--primary); display: flex; font-size: 21px; height: 38px; justify-content: center; width: 38px; }.route__title { display: grid; gap: 5px; min-width: 0; }.route__title strong { font-size: 15px; font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }.route__title small { color: var(--text-sub); font-size: 12px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }.route__time { align-items: center; color: var(--text-sub); display: flex; font-family: Consolas, monospace; font-size: 13px; gap: 7px; white-space: nowrap; }.route__time i { background: var(--border-strong); display: block; height: 1px; width: 14px; }.chevron { color: var(--text-mute); font-size: 20px; transition: transform .2s ease; }.route__summary[aria-expanded="true"] .chevron { transform: rotate(180deg); }.route__detail { border-top: 1px solid var(--border); padding: 16px 20px 20px; }.route__remark { align-items: flex-start; background: var(--info-soft); border-left: 3px solid var(--info); color: var(--info-text); display: flex; font-size: 12px; gap: 7px; line-height: 1.55; margin: 0 0 16px; padding: 9px 10px; }.route__remark .material-icons-outlined { font-size: 16px; }.stops { list-style: none; margin: 0; padding: 0; }.stops li { align-items: center; display: grid; grid-template-columns: 52px 22px minmax(0, 1fr) auto; min-height: 38px; }.stop__time { color: var(--text-sub); font-family: Consolas, monospace; font-size: 12px; }.stop__line { align-self: stretch; position: relative; }.stop__line:before { background: var(--primary); border: 2px solid var(--card); border-radius: 50%; content: ""; height: 8px; left: 5px; position: absolute; top: 14px; width: 8px; z-index: 1; }.stop__line:after { background: var(--primary-border); bottom: -2px; content: ""; left: 9px; position: absolute; top: 20px; width: 1px; }.stops li:last-child .stop__line:after { display: none; }.stop__name { color: var(--text); font-size: 13px; }.stop__tag { background: var(--primary-soft); border-radius: 4px; color: var(--primary); font-size: 11px; padding: 2px 6px; }.state { align-items: center; background: var(--card); border: 1px solid var(--border); border-radius: 8px; color: var(--text-mute); display: flex; flex-direction: column; font-size: 13px; gap: 10px; justify-content: center; min-height: 200px; }.state .material-icons-outlined { font-size: 28px; }.state--error { color: var(--danger); }.spin { animation: spin 1s linear infinite; } @keyframes spin { to { transform: rotate(360deg); } } @media (max-width: 600px) { .masthead__inner { min-height: 92px; padding: 0 16px; }.masthead__icon { font-size: 25px; height: 44px; width: 44px; }.masthead h1 { font-size: 21px; }.content { padding: 22px 16px 36px; }.intro h2 { font-size: 18px; }.route__summary { gap: 10px; grid-template-columns: 34px minmax(0, 1fr) 18px; min-height: 70px; padding: 10px 12px; }.route__mark { font-size: 19px; height: 34px; width: 34px; }.route__time { display: none; }.route__detail { padding: 14px 14px 18px; }.stops li { grid-template-columns: 50px 20px minmax(0, 1fr) auto; } }
</style>
